CREATE TABLE tenants(id uuid PRIMARY KEY, name text NOT NULL, plan text NOT NULL DEFAULT 'growth', status text NOT NULL DEFAULT 'active', ad_limit integer NOT NULL DEFAULT 1000 CHECK(ad_limit>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL, mfa_secret text, mfa_pending text, mfa_last_step bigint NOT NULL DEFAULT -1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(user_id uuid REFERENCES users(id),tenant_id uuid REFERENCES tenants(id),role text NOT NULL CHECK(role IN ('owner','privacy_officer','marketer','developer','auditor')),PRIMARY KEY(user_id,tenant_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid REFERENCES users(id),tenant_id uuid REFERENCES tenants(id),expires_at timestamptz NOT NULL);
CREATE TABLE api_keys(id uuid PRIMARY KEY,tenant_id uuid REFERENCES tenants(id),name text NOT NULL,token_hash text UNIQUE NOT NULL,scopes text[] NOT NULL,revoked_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE controllers(tenant_id uuid REFERENCES tenants(id),id uuid NOT NULL,name text NOT NULL,sender text NOT NULL DEFAULT '',opt_out text NOT NULL DEFAULT '',PRIMARY KEY(tenant_id,id));
CREATE TABLE subjects(tenant_id uuid REFERENCES tenants(id),id uuid NOT NULL,external_id text NOT NULL,kind text NOT NULL DEFAULT 'member',restricted boolean NOT NULL DEFAULT false,deleted_at timestamptz,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,external_id));
CREATE TABLE contact_points(tenant_id uuid,id uuid NOT NULL,subject_id uuid NOT NULL,channel text NOT NULL,encrypted text NOT NULL,value_hmac text NOT NULL,masked text NOT NULL,verified boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,subject_id) REFERENCES subjects(tenant_id,id),UNIQUE(tenant_id,subject_id,channel,value_hmac));
CREATE TABLE purposes(tenant_id uuid,id uuid NOT NULL,controller_id uuid NOT NULL,key text NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('personal_info','advertising_reception','web_tracking')),channel text NOT NULL DEFAULT '',lawful_basis text NOT NULL DEFAULT 'consent',reviewed boolean NOT NULL DEFAULT false,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,controller_id) REFERENCES controllers(tenant_id,id),UNIQUE(tenant_id,key));
CREATE TABLE notices(tenant_id uuid,id uuid NOT NULL,purpose_id uuid NOT NULL,version integer NOT NULL,body text NOT NULL,hash text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','published')),approved_by text,published_at timestamptz,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,purpose_id) REFERENCES purposes(tenant_id,id),UNIQUE(tenant_id,purpose_id,version));
CREATE TABLE consent_events(tenant_id uuid,id uuid NOT NULL,seq bigint GENERATED ALWAYS AS IDENTITY,producer text NOT NULL,idempotency_key text NOT NULL,payload_hash text NOT NULL,subject_id uuid NOT NULL,contact_id uuid,purpose_id uuid NOT NULL,notice_id uuid,scope text NOT NULL,action text NOT NULL CHECK(action IN ('granted','denied','revoked')),evidence text NOT NULL CHECK(evidence IN ('VERIFIED','LEGACY_UNVERIFIED','REVIEW_REQUIRED')),revision integer NOT NULL,occurred_at timestamptz,received_at timestamptz NOT NULL DEFAULT now(),source text NOT NULL,applied boolean NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,subject_id) REFERENCES subjects(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contact_points(tenant_id,id),FOREIGN KEY(tenant_id,purpose_id) REFERENCES purposes(tenant_id,id),FOREIGN KEY(tenant_id,notice_id) REFERENCES notices(tenant_id,id),UNIQUE(tenant_id,producer,idempotency_key),CHECK(action <> 'granted' OR evidence <> 'VERIFIED' OR notice_id IS NOT NULL));
CREATE TABLE consent_current(tenant_id uuid,scope text NOT NULL,subject_id uuid NOT NULL,contact_id uuid,purpose_id uuid NOT NULL,state text NOT NULL CHECK(state IN ('GRANTED','DENIED','REVOKED')),evidence text NOT NULL,revision integer NOT NULL,last_event_id uuid NOT NULL,changed_at timestamptz NOT NULL,grant_at timestamptz,PRIMARY KEY(tenant_id,scope),FOREIGN KEY(tenant_id,last_event_id) REFERENCES consent_events(tenant_id,id),FOREIGN KEY(tenant_id,subject_id) REFERENCES subjects(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contact_points(tenant_id,id),FOREIGN KEY(tenant_id,purpose_id) REFERENCES purposes(tenant_id,id),UNIQUE NULLS NOT DISTINCT(tenant_id,subject_id,contact_id,purpose_id));
CREATE TABLE suppressions(tenant_id uuid,scope text NOT NULL,subject_id uuid NOT NULL,contact_id uuid,purpose_id uuid NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,scope),FOREIGN KEY(tenant_id,subject_id) REFERENCES subjects(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contact_points(tenant_id,id),FOREIGN KEY(tenant_id,purpose_id) REFERENCES purposes(tenant_id,id));
CREATE TABLE templates(tenant_id uuid,id uuid NOT NULL,controller_id uuid NOT NULL,purpose_id uuid,name text NOT NULL,channel text NOT NULL,route text NOT NULL,message_class text NOT NULL CHECK(message_class IN ('marketing','transactional','legal_notice')),body text NOT NULL,title text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft',hash text NOT NULL,approved_by text,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,controller_id) REFERENCES controllers(tenant_id,id),FOREIGN KEY(tenant_id,purpose_id) REFERENCES purposes(tenant_id,id),CHECK(NOT(route='alimtalk' AND message_class='marketing')));
CREATE TABLE decisions(tenant_id uuid,id uuid NOT NULL,subject_id uuid NOT NULL,allowed boolean NOT NULL,reasons text[] NOT NULL,ruleset text NOT NULL,input jsonb NOT NULL,revision integer NOT NULL,evaluated_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,subject_id) REFERENCES subjects(tenant_id,id),CHECK(NOT allowed OR cardinality(reasons)=0));
CREATE TABLE message_jobs(tenant_id uuid,id uuid NOT NULL,subject_id uuid NOT NULL,contact_id uuid NOT NULL,template_id uuid NOT NULL,idempotency_key text NOT NULL,payload_hash text NOT NULL,status text NOT NULL DEFAULT 'queued',scheduled_at timestamptz NOT NULL,reasons text[] NOT NULL DEFAULT '{}',decision_id uuid,provider_id text,attempts integer NOT NULL DEFAULT 0,authorized_at timestamptz,accepted_at timestamptz,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,subject_id) REFERENCES subjects(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contact_points(tenant_id,id),FOREIGN KEY(tenant_id,template_id) REFERENCES templates(tenant_id,id),FOREIGN KEY(tenant_id,decision_id) REFERENCES decisions(tenant_id,id),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE notification_jobs(tenant_id uuid,id uuid NOT NULL,event_id uuid NOT NULL,subject_id uuid NOT NULL,kind text NOT NULL,due_at timestamptz NOT NULL,cycle integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,message_job_id uuid,evidence text,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,event_id) REFERENCES consent_events(tenant_id,id),FOREIGN KEY(tenant_id,subject_id) REFERENCES subjects(tenant_id,id),FOREIGN KEY(tenant_id,message_job_id) REFERENCES message_jobs(tenant_id,id),UNIQUE(tenant_id,event_id,kind,cycle));
CREATE TABLE outbox(tenant_id uuid,id uuid NOT NULL,event_id uuid,kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,event_id) REFERENCES consent_events(tenant_id,id));
CREATE TABLE connectors(tenant_id uuid REFERENCES tenants(id),id uuid NOT NULL,provider text NOT NULL CHECK(provider IN ('mock','solapi')),status text NOT NULL DEFAULT 'not_configured',capabilities jsonb NOT NULL DEFAULT '{}',last_optout_sync timestamptz,mode text NOT NULL DEFAULT 'normal',PRIMARY KEY(tenant_id,id));
CREATE TABLE provider_receipts(tenant_id uuid,job_id uuid NOT NULL,provider_id text NOT NULL,status text NOT NULL,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,job_id),FOREIGN KEY(tenant_id,job_id) REFERENCES message_jobs(tenant_id,id));
CREATE TABLE provider_events(tenant_id uuid REFERENCES tenants(id),id text NOT NULL,received_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE sites(tenant_id uuid,id uuid NOT NULL,controller_id uuid NOT NULL,domain text NOT NULL,verification_token text NOT NULL,verified_at timestamptz,public_key text UNIQUE NOT NULL,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,controller_id) REFERENCES controllers(tenant_id,id));
CREATE TABLE web_configs(tenant_id uuid,site_id uuid NOT NULL,id uuid NOT NULL,version integer NOT NULL,notice text NOT NULL,tags jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'draft',published_at timestamptz,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,site_id,version),FOREIGN KEY(tenant_id,site_id) REFERENCES sites(tenant_id,id));
CREATE TABLE scans(tenant_id uuid,id uuid NOT NULL,site_id uuid NOT NULL,status text NOT NULL DEFAULT 'unverified',result jsonb NOT NULL DEFAULT '{}',created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,site_id) REFERENCES sites(tenant_id,id));
CREATE TABLE deletion_requests(tenant_id uuid,id uuid NOT NULL,subject_id uuid NOT NULL,status text NOT NULL DEFAULT 'open',reason text NOT NULL,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,subject_id) REFERENCES subjects(tenant_id,id));
CREATE TABLE deletion_tasks(tenant_id uuid,id uuid NOT NULL,request_id uuid NOT NULL,system text NOT NULL,status text NOT NULL DEFAULT 'pending',evidence text,hold_until timestamptz,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,request_id) REFERENCES deletion_requests(tenant_id,id));
CREATE TABLE deletion_journal(tenant_id uuid,id uuid NOT NULL,subject_id uuid NOT NULL,deleted_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE audit_log(tenant_id uuid REFERENCES tenants(id),id uuid NOT NULL,actor text NOT NULL,action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE INDEX jobs_due ON message_jobs(tenant_id,scheduled_at) WHERE status='queued';
CREATE INDEX events_subject ON consent_events(tenant_id,subject_id,seq);
CREATE INDEX notices_due ON notification_jobs(tenant_id,due_at) WHERE status='pending';
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable record: append a correction'; END $$;
CREATE TRIGGER event_immutable BEFORE UPDATE OR DELETE ON consent_events FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER decision_immutable BEFORE UPDATE OR DELETE ON decisions FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER deletion_journal_immutable BEFORE UPDATE OR DELETE ON deletion_journal FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE FUNCTION protect_published() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='published' THEN RAISE EXCEPTION 'published version is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER notice_immutable BEFORE UPDATE OR DELETE ON notices FOR EACH ROW EXECUTE FUNCTION protect_published();
CREATE TRIGGER config_immutable BEFORE UPDATE OR DELETE ON web_configs FOR EACH ROW EXECUTE FUNCTION protect_published();
CREATE FUNCTION check_deletion() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='completed' AND (NOT EXISTS(SELECT 1 FROM deletion_tasks WHERE tenant_id=NEW.tenant_id AND request_id=NEW.id) OR EXISTS(SELECT 1 FROM deletion_tasks WHERE tenant_id=NEW.tenant_id AND request_id=NEW.id AND status NOT IN ('verified','retained'))) THEN RAISE EXCEPTION 'unconfirmed deletion tasks'; END IF; RETURN NEW; END $$;
CREATE TRIGGER deletion_completion BEFORE UPDATE ON deletion_requests FOR EACH ROW EXECUTE FUNCTION check_deletion();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['controllers','subjects','contact_points','purposes','notices','consent_events','consent_current','suppressions','templates','decisions','message_jobs','notification_jobs','outbox','connectors','provider_receipts','provider_events','sites','web_configs','scans','deletion_requests','deletion_tasks','deletion_journal','audit_log'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_boundary ON %I USING (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t); END LOOP; END $$;
